import{_ as e,o,c as s,a4 as r}from"./chunks/framework.bruR1JhL.js";const a="/tilepress/screenshots/convert-jpg.webp",m=JSON.parse('{"title":"Format & size","description":"Compress, resize and convert many images at once, and see the new file sizes before you save.","frontmatter":{"title":"Format & size","description":"Compress, resize and convert many images at once, and see the new file sizes before you save."},"headers":[],"relativePath":"docs/img-optimize.md","filePath":"docs/img-optimize.md","lastUpdated":1795509372000}'),n={name:"docs/img-optimize.md"};function i(l,t,d,h,g,c){return o(),s("div",null,[...t[0]||(t[0]=[r('<h1 id="format-size" tabindex="-1">Format &amp; size <a class="header-anchor" href="#format-size" aria-label="Permalink to &quot;Format &amp; size&quot;">​</a></h1><p>These four tools work on a list of images at once. They read JPG, PNG, WebP, HEIC/HEIF (iPhone), AVIF, GIF, BMP, TIFF and ICO, and save JPG, PNG, WebP, AVIF, GIF, BMP or TIFF. Photos are always handled upright: the camera&#39;s rotation flag is applied first. Every tool saves new files and never changes your originals.</p><p>In all four tools:</p><ul><li>Add images with <strong>Add images…</strong>, or drag them from the Explorer onto the list. Remove one with the × at the end of its row, or empty the list with <strong>Clear list</strong>.</li><li>Choose <strong>Save next to each image</strong> (the default) or <strong>Save in a folder</strong> and pick the folder with <strong>Choose…</strong>.</li><li>While the tool works, a progress bar shows which file it&#39;s on. When it&#39;s done, the <strong>Saved</strong> card lists the new files with <strong>Open</strong> and <strong>Show in folder</strong>, and each row shows its result.</li></ul><p>See <a href="/tilepress/docs/interface">The Tilepress window</a> for the Explorer, the Preview pane and the Saved card.</p><h2 id="compress-image" tabindex="-1">Compress Image <a class="header-anchor" href="#compress-image" aria-label="Permalink to &quot;Compress Image&quot;">​</a></h2><p>Makes images smaller for the web, email or storage. Before you save, it compresses each image in memory with your settings and shows the size the file will really have.</p><h3 id="how-to-use-it" tabindex="-1">How to use it <a class="header-anchor" href="#how-to-use-it" aria-label="Permalink to &quot;How to use it&quot;">​</a></h3><ol><li>In the <strong>Images</strong> section, open the <strong>Optimize</strong> tab and choose <strong>Compress Image</strong>.</li><li>Click <strong>Add images…</strong>, or drag images from the Explorer onto the list. You can also right-click an image in the Explorer and choose <strong>Compress image</strong>.</li><li>Pick a preset: <strong>High quality</strong>, <strong>Balanced</strong> or <strong>Smallest</strong>. Or move the <strong>Quality</strong> slider yourself.</li><li>Change the other options if you need to (see below).</li><li>Check the rows. Each one shows the new size, for example &quot;→ 412 KB (−63%)&quot;. The action bar shows the <strong>Estimated total</strong> for the whole list.</li><li>Choose where to save, then click <strong>Compress</strong> (or <strong>Compress 5 images</strong>, for a list of five).</li></ol><h3 id="options" tabindex="-1">Options <a class="header-anchor" href="#options" aria-label="Permalink to &quot;Options&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Option</th><th>What it does</th><th>Default</th></tr></thead><tbody><tr><td><strong>High quality</strong> / <strong>Balanced</strong> / <strong>Smallest</strong></td><td>Presets that set Quality to 85, 72 or 55.</td><td>Balanced</td></tr><tr><td><strong>Format</strong></td><td><strong>Same as the original</strong>, <strong>JPG</strong>, <strong>WebP</strong>, <strong>AVIF</strong> or <strong>PNG</strong>.</td><td>Same as the original</td></tr><tr><td><strong>Quality</strong></td><td>10 to 100. Used for JPG, WebP and AVIF. PNG is lossless and ignores it.</td><td>72</td></tr><tr><td><strong>Limit the size</strong></td><td><strong>Keep the pixel size</strong>, or shrink each image so its longest side is at most 3840, 2560, 1920, 1600, 1280, 1024 or 800 px. Smaller images are not enlarged.</td><td>Keep the pixel size</td></tr><tr><td><strong>PNG colours</strong></td><td>Shown only when the output is PNG. <strong>All (lossless)</strong>, <strong>256 colours (much smaller)</strong>, <strong>128 colours</strong> or <strong>64 colours (smallest)</strong>. Fewer colours means a much smaller file, with dithering to smooth the steps.</td><td>All (lossless)</td></tr><tr><td><strong>Keep metadata (camera details, location)</strong></td><td>Keeps the camera details (EXIF), the colour profile and the DPI. When it&#39;s off, all three are removed.</td><td>Off</td></tr></tbody></table><h3 id="good-to-know" tabindex="-1">Good to know <a class="header-anchor" href="#good-to-know" aria-label="Permalink to &quot;Good to know&quot;">​</a></h3><ul><li>New files are named after the original with <code>_compressed</code> added, for example <code>holiday_compressed.jpg</code>. If that name is taken, Tilepress adds a number: <code>holiday_compressed (2).jpg</code>.</li><li><strong>Same as the original</strong> keeps each file&#39;s format, except HEIC/HEIF photos, which become JPG, and ICO files, which become PNG. Tilepress doesn&#39;t write those two formats.</li><li>If an image can&#39;t get any smaller in its own format and at its own pixel size, Tilepress copies the original file instead of writing a bigger one. Its row then says <strong>Kept original</strong>, and the estimate says &quot;(already small)&quot;. If you change the format or use <strong>Limit the size</strong>, the new file is always written, even if it ends up bigger.</li><li>The sizes are measured, not guessed: each image is compressed in memory with your settings. This is done for the first 60 images in the list, one after another, and starts again shortly after you change a setting.</li><li>With <strong>Keep metadata</strong> off, the colour profile goes too, not just the camera and location details.</li><li>Animated GIFs and multi-page TIFFs are compressed as a single picture: only the first frame or page is kept.</li><li>JPGs are saved as progressive JPGs. At Quality 90 or higher, colour detail is kept at full resolution.</li></ul><h2 id="resize-image" tabindex="-1">Resize Image <a class="header-anchor" href="#resize-image" aria-label="Permalink to &quot;Resize Image&quot;">​</a></h2><p>Scales images by a percentage, to exact pixels, or so the longest side fits a size. Each row shows the size the image will become before you save.</p><h3 id="how-to-use-it-1" tabindex="-1">How to use it <a class="header-anchor" href="#how-to-use-it-1" aria-label="Permalink to &quot;How to use it&quot;">​</a></h3><ol><li>In the <strong>Images</strong> section, open the <strong>Optimize</strong> tab and choose <strong>Resize Image</strong>.</li><li>Click <strong>Add images…</strong>, or drag images from the Explorer onto the list. You can also right-click an image in the Explorer and choose <strong>Resize image</strong>.</li><li>Choose how to size them: <strong>Percentage</strong>, <strong>Pixels</strong> or <strong>Longest side</strong>, and set the size.</li><li>Check the rows. Each one shows the new size, for example &quot;→ 1920 × 1280 px&quot;. &quot;(kept)&quot; means the image stays at its size.</li><li>Choose the <strong>Resampling</strong>, <strong>Format</strong> and <strong>Quality</strong> if you need to.</li><li>Choose where to save, then click <strong>Resize</strong> (or <strong>Resize 5 images</strong>).</li></ol><h3 id="options-1" tabindex="-1">Options <a class="header-anchor" href="#options-1" aria-label="Permalink to &quot;Options&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Option</th><th>What it does</th><th>Default</th></tr></thead><tbody><tr><td><strong>Percentage</strong> → <strong>Scale</strong></td><td>A slider from 5% to 400%, in steps of 5%.</td><td>50%</td></tr><tr><td><strong>Pixels</strong> → <strong>Width (px)</strong> and <strong>Height (px)</strong></td><td>The size you want. Leave one empty (&quot;auto&quot;) and it follows from the image&#39;s proportions.</td><td>Width 1920, Height auto</td></tr><tr><td><strong>Pixels</strong> → <strong>Keep proportions</strong></td><td>When it&#39;s off and you set both width and height, the image is stretched to exactly that size.</td><td>On</td></tr><tr><td><strong>Pixels</strong> → <strong>When both are set</strong></td><td>Shown when <strong>Keep proportions</strong> is on and you set both sizes. <strong>Fit inside (no cropping)</strong> makes the image fit inside the box. <strong>Fill exactly (crop the overflow)</strong> fills the box and trims the overflow equally from both sides.</td><td>Fit inside (no cropping)</td></tr><tr><td><strong>Longest side</strong> → <strong>Longest side (px)</strong></td><td>The longest side becomes this size; the other follows. From 16 to 20,000 px.</td><td>1920</td></tr><tr><td><strong>Resampling</strong></td><td><strong>Lanczos (sharpest)</strong>, <strong>Bicubic (smooth)</strong> or <strong>Nearest (pixel art)</strong>, which keeps hard pixel edges.</td><td>Lanczos (sharpest)</td></tr><tr><td><strong>Format</strong></td><td><strong>Same as the original</strong>, <strong>JPG</strong>, <strong>PNG</strong>, <strong>WebP</strong> or <strong>AVIF</strong>.</td><td>Same as the original</td></tr><tr><td><strong>Quality</strong></td><td>10 to 100, for JPG, WebP and AVIF. Hidden when you choose PNG.</td><td>90</td></tr><tr><td><strong>Never enlarge (images already smaller are kept as they are)</strong></td><td>If the new size would be bigger than the image in either direction, the image keeps its size.</td><td>On</td></tr></tbody></table><h3 id="good-to-know-1" tabindex="-1">Good to know <a class="header-anchor" href="#good-to-know-1" aria-label="Permalink to &quot;Good to know&quot;">​</a></h3><ul><li>New files are named after the original with <code>_resized</code> added, for example <code>holiday_resized.jpg</code>.</li><li>An image that <strong>Never enlarge</strong> leaves at its size is still saved as a new <code>_resized</code> file.</li><li>The result can&#39;t be larger than 200 megapixels. Above that, Tilepress asks you to choose a smaller size.</li><li>The camera details and the colour profile are kept.</li><li>When an image with transparency is saved as JPG, the transparent areas become white.</li><li>Animated GIFs and multi-page TIFFs are resized as a single picture: only the first frame or page is kept.</li></ul><h2 id="convert-to-jpg" tabindex="-1">Convert to JPG <a class="header-anchor" href="#convert-to-jpg" aria-label="Permalink to &quot;Convert to JPG&quot;">​</a></h2><p>Turns PNG, WebP, HEIC (iPhone), AVIF, GIF, BMP, TIFF and ICO images into JPG. Transparent areas get a background colour you choose.</p><p><img src="'+a+'" alt="Convert to JPG after converting a HEIC, a PNG and a WebP photo"></p><h3 id="how-to-use-it-2" tabindex="-1">How to use it <a class="header-anchor" href="#how-to-use-it-2" aria-label="Permalink to &quot;How to use it&quot;">​</a></h3><ol><li>In the <strong>Images</strong> section, open the <strong>Optimize</strong> tab and choose <strong>Convert to JPG</strong>.</li><li>Click <strong>Add images…</strong>, or drag images from the Explorer onto the list. JPG files aren&#39;t accepted here, since they already are JPG.</li><li>Set the <strong>Quality</strong> and the <strong>Background for transparency</strong>.</li><li>Choose where to save, then click <strong>Convert</strong> (or <strong>Convert 5 images</strong>).</li></ol><h3 id="options-2" tabindex="-1">Options <a class="header-anchor" href="#options-2" aria-label="Permalink to &quot;Options&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Option</th><th>What it does</th><th>Default</th></tr></thead><tbody><tr><td><strong>Quality</strong></td><td>10 to 100.</td><td>90</td></tr><tr><td><strong>Background for transparency</strong></td><td>The colour that fills transparent areas, since JPG can&#39;t store transparency.</td><td>White</td></tr><tr><td><strong>Keep metadata and colour profile</strong></td><td>Keeps the camera details (EXIF), the colour profile and the DPI.</td><td>On</td></tr><tr><td><strong>Every page / frame as its own JPG (multi-page TIFF, animated GIF)</strong></td><td>Shown when the list has a GIF or TIFF. Saves each page or frame as its own JPG. When it&#39;s off, only the first page or frame is converted.</td><td>Off</td></tr></tbody></table><h3 id="good-to-know-2" tabindex="-1">Good to know <a class="header-anchor" href="#good-to-know-2" aria-label="Permalink to &quot;Good to know&quot;">​</a></h3><ul><li>New files keep the original&#39;s name with a <code>.jpg</code> extension: <code>logo.png</code> becomes <code>logo.jpg</code>. If that name is taken, Tilepress adds a number: <code>logo (2).jpg</code>.</li><li>With <strong>Every page / frame as its own JPG</strong>, the files are numbered: <code>scan_1.jpg</code>, <code>scan_2.jpg</code> and so on.</li><li>After converting, each row shows the name of the file it was saved as.</li></ul><h2 id="convert-from-jpg" tabindex="-1">Convert from JPG <a class="header-anchor" href="#convert-from-jpg" aria-label="Permalink to &quot;Convert from JPG&quot;">​</a></h2><p>Exports JPG photos as PNG, WebP, AVIF, GIF, BMP or TIFF, or puts them into a PDF: one document for all of them, or one per photo.</p><h3 id="how-to-use-it-3" tabindex="-1">How to use it <a class="header-anchor" href="#how-to-use-it-3" aria-label="Permalink to &quot;How to use it&quot;">​</a></h3><ol><li>In the <strong>Images</strong> section, open the <strong>Optimize</strong> tab and choose <strong>Convert from JPG</strong>.</li><li>Click <strong>Add images…</strong>, or drag JPG photos (<code>.jpg</code>, <code>.jpeg</code> or <code>.jfif</code>) from the Explorer onto the list.</li><li>Choose the new format: <strong>PNG</strong>, <strong>WebP</strong>, <strong>AVIF</strong>, <strong>GIF</strong>, <strong>BMP</strong>, <strong>TIFF</strong> or <strong>PDF</strong>.</li><li>Set the options for that format (see below).</li><li>To save pictures, or one PDF per photo: choose where to save, then click <strong>Convert</strong> (or <strong>Convert 5 images</strong>).</li><li>To make one PDF from all the photos: click <strong>Create PDF…</strong> and choose a name and folder in the Save dialog.</li></ol><h3 id="options-3" tabindex="-1">Options <a class="header-anchor" href="#options-3" aria-label="Permalink to &quot;Options&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Option</th><th>What it does</th><th>Default</th></tr></thead><tbody><tr><td>Format</td><td><strong>PNG</strong>, <strong>WebP</strong>, <strong>AVIF</strong>, <strong>GIF</strong>, <strong>BMP</strong>, <strong>TIFF</strong> or <strong>PDF</strong>.</td><td>PNG</td></tr><tr><td><strong>Quality</strong></td><td>10 to 100. Shown for WebP and AVIF only; the other picture formats are lossless.</td><td>90</td></tr><tr><td><strong>PDF</strong></td><td>For PDF: <strong>All photos in one PDF (list order)</strong> or <strong>One PDF per photo</strong>.</td><td>All photos in one PDF (list order)</td></tr><tr><td><strong>Page size</strong></td><td>For PDF: <strong>Same as the photo</strong>, <strong>A4</strong> or <strong>Letter</strong>.</td><td>Same as the photo</td></tr></tbody></table><h3 id="good-to-know-3" tabindex="-1">Good to know <a class="header-anchor" href="#good-to-know-3" aria-label="Permalink to &quot;Good to know&quot;">​</a></h3><ul><li>Pictures keep the original&#39;s name with the new extension: <code>photo.jpg</code> becomes <code>photo.png</code>, <code>photo.webp</code> and so on. TIFF files get the <code>.tif</code> extension.</li><li>PNG is lossless: the file is usually bigger than the JPG, but nothing more is lost.</li><li>GIF can only hold 256 colours, so photos saved as GIF are reduced to 256 colours, with dithering. TIFF files are saved with lossless compression.</li><li>The camera details and the colour profile are kept where the new format can store them.</li><li>In a PDF, each photo&#39;s JPG data is placed into the PDF exactly as it is, so there&#39;s no loss of quality. The camera&#39;s rotation flag is applied, so photos appear upright.</li><li><strong>Same as the photo</strong> makes each page exactly the size of its photo, with no margin. <strong>A4</strong> and <strong>Letter</strong> leave a 10 mm margin, turn the page to landscape for landscape photos, and fit the photo inside, centred.</li><li><strong>All photos in one PDF</strong> uses the order in which you added the photos. The Save dialog suggests the first photo&#39;s name with <code>.pdf</code>, in the same folder.</li><li><strong>One PDF per photo</strong> names each PDF after its photo, for example <code>photo.pdf</code>.</li><li>For more control over PDFs made from pictures (other image formats, rotating each picture, orientation, margins), use <strong>JPG to PDF</strong> in <a href="/tilepress/docs/to-pdf">Convert to PDF</a>.</li></ul>',38)])])}const f=e(n,[["render",i]]);export{m as __pageData,f as default};
